func getTargetForRedirect(target string, domain string) string {
	if len(target) == 0 {
		return "https://" + domain
	}

	// Check if target starts with https://
	if len(target) >= 8 && target[:8] == "https://" {
		// Extract the domain part from target
		targetDomain := target[8:]
		// Find the first '/' to split the domain and path
		slashIndex := -1
		for i, c := range targetDomain {
			if c == '/' {
				slashIndex = i
				break
			}
		}
		if slashIndex == -1 {
			// No path, just the domain
			if targetDomain == domain {
				return target
			}
			return "https://" + domain
		} else {
			// Check if the domain part matches the provided domain
			if targetDomain[:slashIndex] == domain {
				return target
			}
			return "https://" + domain
		}
	} else {
		// If target doesn't start with https://, fallback to domain
		return "https://" + domain
	}
}
