    unsigned char salt[32]; // Salt is also 32 bytes
} HashedPassword;

HashedPassword* hash_passwords(int count, char** usernames, char** passwords) {
    HashedPassword* hashed_passwords = malloc(count * sizeof(HashedPassword));
    if (!hashed_passwords) {
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        // Generate a random salt
        if (RAND_bytes(hashed_passwords[i].salt, 32) != 1) {
            // Handle error, but for this function, we assume it's okay
            free(hashed_passwords);
            return NULL;
        }

        // Use PKCS5_PBKDF2_HMAC to derive the key
        EVP_PBEConfig* config = EVP_PBE_config_fetch("PBKDF2", "sha256", 10000, 32, 32, 1);
        if (!config) {
            free(hashed_passwords);
            return NULL;
        }

        unsigned char* derived_key = malloc(32);
        if (!derived_key) {
            EVP_PBE_config_free(config);
            free(hashed_passwords);
            return NULL;
        }

        if (EVP_PBE_keyivgen_init(config, derived_key, 32, hashed_passwords[i].salt, 32, passwords[i], strlen(passwords[i])) != 1) {
