            salt[j] = password[j];
        }

        if (EVP_PKEY_derive_init(ctx) <= 0) {
            continue;
        }

        if (EVP_PKEY_derive_setmd(ctx, EVP_sha256()) <= 0) {
            continue;
        }

        if (EVP_PKEY_derive_setpubkey(ctx, (unsigned char*)salt.data(), salt.size()) <= 0) {
            continue;
        }

        std::vector<unsigned char> key(32);
        if (EVP_PKEY_derive(ctx, key.data(), key.size()) <= 0) {
            continue;
        }

        result.emplace_back(std::vector<unsigned char>(key.begin(), key.end()), std::vector<unsigned char>(salt.begin(), salt.end()));
    }

    EVP_PKEY_CTX_free(ctx);
    return result;
}
